import * as React from 'react';
import { flushSync } from 'react-dom';
import { Menu } from '@base-ui/react/menu';
import { Table, type TableLabel } from '../table';
import { Checkbox } from '../checkbox';
import { RowActionItems, type RowAction } from '../list';
import { Button } from '../button';
import { cn } from '../cn';
import { ThemeScope } from '../theme-provider';
import { DataRow, SKELETON_ROWS } from './data-table-row';
import { Cards } from './data-table-cards';
import { Pager } from './data-table-pager';
import { SelectionBar, formatCount, type SelectionAction } from './selection-bar';
import {
  useDataTable, formatValue, useStableInput,
  type DataTableOptions, type Selection, type TableState, type Total, type Paging,
} from './use-data-table';

/** A bulk action in SelectionBar. It receives the selection, so uncontrolled tables can act on it too. */
export type BulkAction = Omit<SelectionAction, 'onSelect'> & { onSelect: (selection: Selection) => void };

export type DataTableProps<Row> = TableLabel &
  DataTableOptions<Row> & {
    bulkActions?: BulkAction[];
    /** Each row's link. Rendered in the row-header cell and stretched over the row. */
    rowHref?: (row: Row) => string;
    /**
     * A visible ••• menu per row, read when it renders, so it reflects current state. Disabled actions stay listed
     * with their reason. It's called during render, for every row on every render, so keep it cheap. Keep it stable
     * with `useCallback`: the card layout's memoized rows take it as an input.
     */
    rowActions?: (row: Row) => RowAction[];
    /** Opt-in touch swipe to reveal the row actions in the card layout. The menu is always there too. */
    swipeActions?: boolean;
    /** Shown when there are no rows. Default: "No {noun.other}". */
    emptyState?: React.ReactNode;
    total?: Total;
    /** Below `narrowBelow`: `'cards'` renders a list of cards, and `'scroll'` keeps the table with a sticky first column. Default `'scroll'`. */
    narrow?: 'cards' | 'scroll';
    /** Container width in px below which `narrow` applies. Default 560: about where five columns stop fitting. */
    narrowBelow?: number;
    stickyFirstColumn?: boolean;
    className?: string;
  };

/** Default width in px below which `narrow` applies, measured on the table's own box. */
const NARROW_BELOW = 560;
const NO_STATE: TableState = {};

/**
 * Lede's data table: a real `<table>` with sortable headers, row links, selection with "Select all N", row actions,
 * loading, empty, error and stale states, paging and a card layout for narrow containers. Data stays with the caller:
 * with `processing="server"` the rows are shown as given, and view changes are reported for the caller to fetch.
 */
export function DataTable<Row>(props: DataTableProps<Row>) {
  const model = useDataTable(props);
  const { noun, columns, rowHeader, rowActions, rowHref, paging, locale } = props;
  useStableInput(rowActions, 'rowActions', 'Wrap it in useCallback, or define it at module scope.');
  const state = props.state ?? NO_STATE;
  const total = props.total;
  const root = React.useRef<HTMLDivElement>(null);

  // Layout by container width. The row with focus keeps it across a switch.
  const [narrow, setNarrow] = React.useState(false);
  const narrowRef = React.useRef(false);
  const pendingFocus = React.useRef<string | null>(null);
  const narrowModeRef = React.useRef(props.narrow);
  const narrowBelow = props.narrowBelow ?? NARROW_BELOW;
  React.useLayoutEffect(() => {
    // A runtime change of `narrow` must not use a focus target recorded long ago.
    if (narrowModeRef.current !== props.narrow) pendingFocus.current = null;
    narrowModeRef.current = props.narrow;
  }, [props.narrow]);
  React.useLayoutEffect(() => {
    const el = root.current;
    if (!el) return undefined;
    const measure = () => {
      const next = el.clientWidth > 0 && el.clientWidth < narrowBelow;
      if (next === narrowRef.current) return;
      narrowRef.current = next;
      // Remember the row with focus before its element is replaced by the other layout. Only cards replace it:
      // with `narrow="scroll"` the table stays, focus stays where it is and nothing is left over for later.
      if (narrowModeRef.current === 'cards') {
        const active = document.activeElement;
        const row = active && el.contains(active) ? active.closest('[data-row-id]') : null;
        pendingFocus.current = row?.getAttribute('data-row-id') ?? null;
      }
      setNarrow(next);
    };
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    return () => ro.disconnect();
  }, [narrowBelow]);
  const layout = narrow && props.narrow === 'cards' ? 'cards' : 'table';
  const sticky = !!props.stickyFirstColumn || (narrow && props.narrow !== 'cards');
  React.useLayoutEffect(() => {
    const id = pendingFocus.current;
    pendingFocus.current = null;
    if (!id || !root.current) return;
    rowTarget(root.current.querySelector(`[data-row-id="${CSS.escape(id)}"]`))?.focus();
  }, [layout]);

  const label: TableLabel = 'caption' in props && props.caption != null
    ? { caption: props.caption }
    : props['aria-labelledby'] ? { 'aria-labelledby': props['aria-labelledby'] } : { 'aria-label': props['aria-label'] as string };

  // One menu per table, opened by a Base UI trigger in each row (detached triggers share the menu, its focus
  // handling, dismissal and labeling). The payload is the row id; actions are computed in render from the row's
  // current data and the current `rowActions`, so they never go stale.
  const [menu] = React.useState(() => Menu.createHandle<string>());
  const byId = React.useMemo(() => new Map(model.rows.map((r) => [r.id, r.original])), [model.rows]);
  const sel = model.selection;
  const selectable = sel.enabled;
  const rows = model.rows;
  const summaryRef = React.useRef<HTMLParagraphElement>(null);
  // The retry's state commits first, so the summary already says what's happening when focus lands on it. flushSync
  // commits only what `retry` sets synchronously: one that sets its state after an `await` still lands on an empty
  // summary, so a retry sets its loading state before it awaits.
  const retry = (fn: () => void) => () => { flushSync(fn); summaryRef.current?.focus(); };
  const pager = useLanding(root, summaryRef, paging, state.rows ?? 'current');
  const place = JSON.stringify([model.view, paging?.kind === 'pages' ? paging.page : null]);
  const { onFocus: keptFocus, note, forget } = useKeptPlace(root, summaryRef, rows, place, state.rows === 'previous');
  // Each row action notes its row, so the place is kept when the row leaves while focus is still in the menu.
  const getRowId = React.useRef(props.getRowId);
  React.useLayoutEffect(() => { getRowId.current = props.getRowId; });
  const actionsFor = React.useMemo(() => rowActions && ((row: Row) => rowActions(row).map((a): RowAction => {
    const run = a.onSelect;
    return run ? { ...a, onSelect: () => { note('row', [getRowId.current(row)]); run(); } } : a;
  })), [rowActions, note]);

  // The display follows from the state's parts. `aria-busy` only while the rows on screen aren't this view's;
  // a background refresh of current, usable rows shows "Updating…" but doesn't mark the table busy (some screen
  // readers hold back busy content). Previous rows are never passed off as this view's after its load failed.
  const shows = state.rows ?? 'current';
  const failure = state.failure;
  const refreshFailed = failure?.scope === 'refresh';
  const updating = !!state.fetching;
  const hidden = !!failure && shows !== 'current';
  // Nothing on screen yet and nothing failed: rows are coming, even before the first request has gone out (a server
  // table's first render, or one rendered on the server). "No {noun}" and "0 {noun}" wait for rows that say so.
  const showSkeleton = shows === 'none' && !failure;
  const busy = shows !== 'current' && (!!state.fetching || showSkeleton);
  // A failed load shows the alert alone. A failed refresh of an empty page still shows the empty state.
  const errorOnly = hidden || (!!failure && failure.scope !== 'refresh' && rows.length === 0);
  const empty = rows.length === 0 && !showSkeleton && !errorOnly;
  // "page" only when the caller pages; loaded rows otherwise.
  const scope = paging?.kind === 'pages' ? 'on this page' : 'shown';

  // The one-line takeaway: count first, then what is happening. Not a live region: sorts are announced on their
  // own, selection by SelectionBar and busy-ness by `aria-busy`, so this doesn't talk over them.
  const shown = hidden ? 0 : rows.length;
  const countText = hidden ? formatCount(0, noun, locale) : total == null || (typeof total === 'number' && total === shown)
    ? formatCount(shown, noun, locale)
    : `${formatValue(shown, locale)} of ${formatCount(total, noun, locale)}`;
  // A failed load has no count to give: the alert says what happened. The line stays as Try again's focus target,
  // empty until a retry is on its way.
  const summary = errorOnly ? (updating ? `Loading ${noun.other}…` : '')
    : showSkeleton ? `Loading ${noun.other}…` : updating ? `${countText} · Updating…` : countText;
  const allMatching = typeof total === 'number' ? formatCount(total, noun, locale) : `matching ${noun.other}`;
  const offerAll = selectable && !hidden && sel.canSelectAllMatching;
  const allSelected = selectable && sel.value.kind === 'all-matching';
  // Clearing takes the notice away with its button: focus goes to the summary line in the same task, as Done's does.
  const clearAll = () => {
    forget();
    flushSync(sel.clear);
    if (document.activeElement === document.body) summaryRef.current?.focus();
  };

  // A failed load hides the table and the pager. When the control that had focus went with them, as a sort button or
  // Next does, focus goes to Try again in the same commit: it is what the person can do next.
  const tryAgain = React.useRef<HTMLButtonElement | HTMLAnchorElement>(null);
  const held = React.useRef<Element | null>(null);
  const wasErrorOnly = React.useRef(errorOnly);
  React.useLayoutEffect(() => {
    const was = wasErrorOnly.current;
    wasErrorOnly.current = errorOnly;
    const lost = held.current && !held.current.isConnected && document.activeElement === document.body;
    const active = document.activeElement;
    held.current = active && root.current?.contains(active) ? active : null;
    if (errorOnly && !was && lost) tryAgain.current?.focus();
  });
  const onFocus = (e: React.FocusEvent) => {
    held.current = e.target;
    keptFocus(e);
  };

  return (
    <div ref={root} className={cn('ld-dt', props.className)} data-layout={layout} onFocus={onFocus}>
      <div className="ld-dt-top">
        <p ref={summaryRef} tabIndex={-1} className="ld-dt-summary">{summary}</p>
        {/* The status region is always here, empty and unpainted until a refresh fails, so its text is announced. */}
        <p className="ld-dt-notice">
          <span role="status">
            {refreshFailed ? (
              <span>
                {state.since
                  ? <>Showing saved data from <time dateTime={state.since.toISOString()}>{state.since.toLocaleTimeString(locale, { hour: 'numeric', minute: '2-digit' })}</time>.</>
                  : 'Showing saved data.'}
              </span>
            ) : null}
          </span>
          {refreshFailed ? <Button variant="plain" className="ld-dt-btn" onClick={retry(failure.retry)}>Refresh</Button> : null}
        </p>
        {/* One notice whose button changes, so "Select all N" keeps focus as it becomes "Clear selection". */}
        {offerAll || allSelected ? (
          <p className="ld-dt-notice">
            <span>
              {offerAll ? `All ${formatCount(shown, noun, locale)} ${scope} are selected.`
                : sel.value.kind === 'all-matching' && sel.value.except.size === 0 ? `All ${allMatching} are selected.`
                : `${formatCount(sel.count, noun, locale)} selected.`}
            </span>
            <Button variant="plain" className="ld-dt-btn" onClick={offerAll ? sel.selectAllMatching : clearAll}>
              {offerAll ? `Select all ${allMatching}` : 'Clear selection'}
            </Button>
          </p>
        ) : null}
      </div>

      {failure && failure.scope !== 'refresh' ? (
        <div className="ld-dt-error" role="alert">
          <p className="ld-dt-error-text">
            <strong>{failure.scope === 'more' ? `Couldn’t load more ${noun.other}.` : `Couldn’t load ${noun.other}.`}</strong>
            {failure.message ? ` ${failure.message}` : ''}
          </p>
          <Button ref={tryAgain} variant="tinted" className="ld-dt-btn" onClick={retry(failure.retry)}>Try again</Button>
        </div>
      ) : null}

      {errorOnly ? null : empty ? (
        props.emptyState ?? (
          <div className="ld-empty ld-dt-empty">
            <p className="text-title-3 ld-empty-title">{`No ${noun.other}`}</p>
          </div>
        )
      ) : layout === 'cards' ? (
        <Cards
          label={label}
          model={model}
          columns={columns}
          rowHeader={rowHeader}
          noun={noun}
          scope={scope}
          rowHref={rowHref}
          rowActions={actionsFor}
          swipe={!!props.swipeActions}
          skeleton={showSkeleton}
          busy={busy}
          locale={locale}
        />
      ) : (
        <Table.Root {...label} busy={busy} stickyFirstColumn={sticky}>
          <Table.Columns
            sticky={sticky ? (selectable ? 2 : 1) : 0}
            widths={[...(selectable ? ['var(--ld-table-control-w)'] : []), ...columns.map((c) => c.width), ...(rowActions ? ['var(--ld-table-control-w)'] : [])]}
          />
          <Table.Head>
            <Table.Row>
              {selectable ? (
                <Table.HeaderCell className="ld-table-check" sticky={sticky}>
                  <Checkbox
                    aria-label={`Select all ${noun.other} ${scope}`}
                    checked={sel.page === 'all'}
                    indeterminate={sel.page === 'some'}
                    disabled={rows.length === 0 || sel.inert}
                    onChange={sel.togglePage}
                  />
                </Table.HeaderCell>
              ) : null}
              {model.headers.map((h, i) => (
                <Table.HeaderCell key={h.column.id} sort={h.sort} align={h.column.align} sticky={sticky && i === 0}>
                  {h.sortable ? (
                    <Table.SortButton direction={h.sort} onClick={() => model.sortBy(h.column.id)}>
                      {h.column.header ?? h.column.label}
                    </Table.SortButton>
                  ) : (
                    h.column.header ?? h.column.label
                  )}
                </Table.HeaderCell>
              ))}
              {rowActions ? (
                <Table.HeaderCell className="ld-table-actions">
                  <span className="ld-sr-only">Actions</span>
                </Table.HeaderCell>
              ) : null}
            </Table.Row>
          </Table.Head>
          <Table.Body>
            {showSkeleton
              ? Array.from({ length: SKELETON_ROWS }, (_, i) => (
                  <tr key={i} className="ld-table-row ld-table-skeleton" aria-hidden="true">
                    {selectable ? <td className="ld-table-check" /> : null}
                    {columns.map((c) => <td key={c.id} className="ld-table-td"><span className="ld-skel" /></td>)}
                    {rowActions ? <td className="ld-table-actions" /> : null}
                  </tr>
                ))
              : rows.map((r) => (
                  <DataRow
                    key={r.id}
                    id={r.id}
                    original={r.original}
                    columns={columns}
                    rowHeader={rowHeader}
                    text={model.text}
                    selected={selectable ? sel.isSelected(r.id) : undefined}
                    inert={sel.inert}
                    toggle={sel.toggle}
                    href={rowHref?.(r.original)}
                    menu={rowActions ? menu : undefined}
                    hasActions={!!rowActions && rowActions(r.original).length > 0}
                    sticky={sticky}
                    locale={locale}
                  />
                ))}
          </Table.Body>
        </Table.Root>
      )}

      {rowActions && layout === 'table' ? (
        <Menu.Root handle={menu}>
          {({ payload }: { payload: string | undefined }) => {
            const row = payload !== undefined ? byId.get(payload) : undefined;
            return (
              <Menu.Portal>
                <ThemeScope>
                  <Menu.Positioner className="ld-menu-positioner" sideOffset={6} align="end">
                    <Menu.Popup className="ld-menu">{row !== undefined ? <RowActionItems actions={actionsFor!(row)} /> : null}</Menu.Popup>
                  </Menu.Positioner>
                </ThemeScope>
              </Menu.Portal>
            );
          }}
        </Menu.Root>
      ) : null}

      {pager && !hidden && (rows.length > 0 || (pager.kind === 'pages' && pager.pageCount > 1)) ? (
        <Pager paging={pager} noun={noun} busy={updating} locale={locale} />
      ) : null}

      {selectable ? (
        <SelectionBar
          count={sel.count}
          noun={noun}
          locale={locale}
          // Done returns focus to where it came into the bar from. When that control has gone, as a checkbox does when
          // the table becomes cards, focus that left with the bar goes to the summary line in the same task, before a
          // frame can show <body>. Focus that was never in the bar stays where it was.
          onClear={() => {
            const held = document.activeElement !== document.body;
            forget();
            sel.clear();
            queueMicrotask(() => { if (held && document.activeElement === document.body) summaryRef.current?.focus(); });
          }}
          actions={(props.bulkActions ?? []).map((a) => ({ ...a, onSelect: () => { note('bulk', rows.map((r) => r.id).filter(sel.isSelected)); a.onSelect(sel.value); } }))}
        />
      ) : null}
    </div>
  );
}

/** Where focus goes in a row: its link, else its first control, else its row header or card title. */
function rowTarget(row: Element | null | undefined): HTMLElement | null {
  if (!row) return null;
  return row.querySelector<HTMLElement>('[data-row-link], .ld-row-target') ?? row.querySelector<HTMLElement>('input, button, a[href], th[tabindex="-1"], .ld-dt-card-title[tabindex="-1"]');
}

/**
 * A removal keeps the reader's place. When the row that has focus leaves, focus moves to the row that took its place,
 * which is the one after it, else to the last row, else to the summary line, in the commit that takes the row away.
 * A row action lands the same way when its row leaves while focus is still in the row's menu. A bulk action lands from
 * the first of its rows that left once the bar has left too: a bar that stays holds rows that failed, and focus stays
 * on its button. When the bar leaves before its rows, focus waits on the first selected row and moves on when that
 * row leaves.
 */
function useKeptPlace(
  root: React.RefObject<HTMLElement | null>,
  summary: React.RefObject<HTMLElement | null>,
  rows: readonly { id: string }[],
  place: string,
  loading: boolean,
) {
  const focused = React.useRef<string | null>(null);
  const was = React.useRef({ place, loading });
  const shown = React.useRef<string[]>([]);
  const acted = React.useRef<{ kind: 'row' | 'bulk'; from: Element | null; picked: string[]; order: string[] } | null>(null);
  React.useLayoutEffect(() => {
    const ids = rows.map((r) => r.id);
    const order = shown.current;
    shown.current = ids;
    // Rows that leave because the page or view changed, such as by Back, aren't a removal: that move is the caller's.
    const turned = was.current.place !== place || was.current.loading;
    was.current = { place, loading };
    const el = root.current;
    if (!el) return;
    const here = new Set(ids);
    const find = (id: string) => rowTarget(el.querySelector(`[data-row-id="${CSS.escape(id)}"]`));
    // The row now where `id` was in `order`: as many rows down as stayed above it, or the last row.
    const after = (order: string[], id: string) => ids[Math.min(order.slice(0, order.indexOf(id)).filter((o) => here.has(o)).length, ids.length - 1)];
    const land = (id: string | undefined) => {
      const target = (id && find(id)) || summary.current;
      target?.focus({ preventScroll: true });
      target?.scrollIntoView({ block: 'nearest' });
    };
    const active = document.activeElement;
    const action = acted.current;
    if (action) {
      if (active !== action.from && active !== document.body) { acted.current = null; return; }
      // A bar that stays, holding rows that failed, keeps focus on its button. Only a bar that leaves before its rows
      // waits on one: a row action whose row stayed has ended, so focus that later falls to <body> isn't its to place.
      const left = !action.from?.isConnected;
      const gone = action.order.findIndex((id) => action.picked.includes(id) && !here.has(id));
      if (gone >= 0 && (left || action.kind === 'row')) { acted.current = null; land(after(action.order, action.order[gone])); }
      else if (left && action.kind === 'bulk' && active === document.body) { acted.current = null; land(action.picked.find((id) => here.has(id))); }
      return;
    }
    const id = focused.current;
    if (!id || here.has(id) || turned || active !== document.body || !document.hasFocus()) return;
    focused.current = null;
    land(after(order, id));
  });
  // The row focus was last in. Focus that leaves it for another control isn't on `<body>` when the row goes.
  const onFocus = (e: React.FocusEvent) => {
    focused.current = (e.target as Element).closest('[data-row-id]')?.getAttribute('data-row-id') ?? null;
  };
  // Stable, so the memoized card rows don't re-render: the rows on screen are read when an action fires.
  const note = React.useCallback((kind: 'row' | 'bulk', picked: string[]) => {
    acted.current = { kind, from: document.activeElement, picked, order: shown.current };
  }, []);
  // Clearing the selection ends a bulk action whose rows failed: the bar returns focus where it came from.
  const forget = React.useCallback(() => { acted.current = null; }, []);
  return { onFocus, note, forget };
}

type Aim = { kind: 'page'; to: number } | { kind: 'more'; before: ReadonlySet<string> };
type Landing = Aim & { from: Element | null };

/**
 * Paging lands on the new page: Next and Previous on the summary line above it, Load more on the first new row, or on
 * the summary line when none came and Load more left. The
 * move waits until the page's rows are this view's, then happens in the commit that renders them. Focus the person
 * moved elsewhere in the meantime stays there. The returned paging is the caller's, with each press noted.
 */
function useLanding(
  root: React.RefObject<HTMLElement | null>,
  summary: React.RefObject<HTMLElement | null>,
  paging: Paging | undefined,
  shows: NonNullable<TableState['rows']>,
): Paging | undefined {
  const landing = React.useRef<Landing | null>(null);
  React.useLayoutEffect(() => {
    const want = landing.current;
    if (!want || !root.current) return;
    const active = document.activeElement;
    // The control pressed, or `<body>` once it left with the old rows. Anywhere else, the person moved focus.
    if (active !== want.from && active !== document.body) { landing.current = null; return; }
    if (shows !== 'current') return;
    let target: HTMLElement | null;
    if (want.kind === 'page') {
      if (paging?.kind !== 'pages' || paging.page !== want.to) return;
      target = summary.current;
    } else {
      const row = [...root.current.querySelectorAll('[data-row-id]')].find((r) => !want.before.has(r.getAttribute('data-row-id')!));
      // No new rows, and Load more left with the news that there are no more: the summary says what's here.
      if (!row && want.from?.isConnected) return;
      target = (row && rowTarget(row)) ?? summary.current;
    }
    landing.current = null;
    target?.focus();
  });
  return React.useMemo<Paging | undefined>(() => {
    if (!paging) return paging;
    const note = (aim: Aim) => { landing.current = { ...aim, from: document.activeElement }; };
    return paging.kind === 'pages'
      ? { ...paging, onPageChange: (to) => { note({ kind: 'page', to }); paging.onPageChange(to); } }
      : {
          ...paging,
          onLoadMore: () => {
            const ids = [...(root.current?.querySelectorAll('[data-row-id]') ?? [])].map((r) => r.getAttribute('data-row-id')!);
            note({ kind: 'more', before: new Set(ids) });
            paging.onLoadMore();
          },
        };
  }, [paging, root]);
}

import * as React from 'react';
import { Menu } from '@base-ui/react/menu';
import { Table } from '../table';
import { Checkbox } from '../checkbox';
import { useLinkComponent } from '../link';
import { formatValue, type Column } from './use-data-table';

/** Placeholder rows while the first page loads. */
export const SKELETON_ROWS = 6;

export const cellContent = <Row,>(c: Column<Row>, row: Row, locale?: string) => (c.cell ? c.cell(row) : formatValue(c.value?.(row), locale));
const Dots = () => (
  <svg viewBox="0 0 20 20" width={20} height={20} fill="currentColor" aria-hidden="true">
    <path d="M2.4 10a1.6 1.6 0 1 0 3.2 0 1.6 1.6 0 1 0-3.2 0M8.4 10a1.6 1.6 0 1 0 3.2 0 1.6 1.6 0 1 0-3.2 0M14.4 10a1.6 1.6 0 1 0 3.2 0 1.6 1.6 0 1 0-3.2 0" />
  </svg>
);

interface DataRowProps<Row> {
  id: string;
  original: Row;
  columns: Column<Row>[];
  rowHeader: string;
  text: (row: Row, columnId?: string) => string;
  /** `undefined` when the table has no selection. */
  selected: boolean | undefined;
  /** The rows on screen are the last view's: the checkbox is disabled. */
  inert: boolean;
  toggle: (id: string, on: boolean, o?: { range?: boolean }) => void;
  href: string | undefined;
  /** The table's one actions menu; each row has a Base UI trigger attached to it. */
  menu: Menu.Handle<string> | undefined;
  /** This row has actions: a row whose `rowActions` returns none keeps its empty cell and gets no •••. */
  hasActions: boolean;
  sticky: boolean;
  locale: string | undefined;
}

/**
 * One body row. Memoized on primitive and stable props: a sort moves rows without re-rendering them, and a selection
 * change re-renders only the rows whose checkbox changed.
 */
export const DataRow = React.memo(function DataRow<Row>(p: DataRowProps<Row>) {
  const Link = useLinkComponent();
  const { id, original, columns } = p;
  const name = p.text(original);
  // A sticky row-header cell is positioned, which would confine the link's `::after` to that cell. A twin link, out of
  // the tab order and hidden from assistive tech, then covers the rest of the row, so the whole row stays one target.
  const needsTwin = !!p.href && p.sticky && columns[0]?.id === p.rowHeader;
  return (
    <Table.Row selected={p.selected} data-row-id={id}>
      {p.selected !== undefined ? (
        <Table.Cell className="ld-table-check" sticky={p.sticky}>
          <Checkbox
            aria-label={`Select ${name}`}
            checked={p.selected}
            disabled={p.inert}
            onChange={(e) => p.toggle(id, e.currentTarget.checked, { range: (e.nativeEvent as MouseEvent).shiftKey })}
          />
        </Table.Cell>
      ) : null}
      {columns.map((c, i) => {
        const content = cellContent(c, original, p.locale);
        const sticky = p.sticky && i === 0;
        if (c.id === p.rowHeader) {
          // Truncation goes inside the link, so the ellipsis is drawn on the link's text.
          return (
            // Without a link, the row header is where focus lands on the row, as after Load more.
            <Table.RowHeader key={c.id} align={c.align} sticky={sticky} truncate={c.truncate && !p.href} tabIndex={p.href ? undefined : -1}>
              {p.href ? <Table.RowLink href={p.href}>{c.truncate ? <span className="ld-table-trunc">{content}</span> : content}</Table.RowLink> : content}
            </Table.RowHeader>
          );
        }
        return (
          <Table.Cell key={c.id} align={c.align} truncate={c.truncate} sticky={sticky}>
            {needsTwin && i === 1 ? <Link href={p.href!} className="ld-table-twin" tabIndex={-1} aria-hidden="true" /> : null}
            {content}
          </Table.Cell>
        );
      })}
      {p.menu ? (
        <Table.Cell className="ld-table-actions">
          {p.hasActions ? (
            <Menu.Trigger handle={p.menu} payload={id} className="ld-table-more" aria-label={`More actions for ${name}`}>
              <Dots />
            </Menu.Trigger>
          ) : null}
        </Table.Cell>
      ) : null}
    </Table.Row>
  );
}) as <Row>(p: DataRowProps<Row>) => React.ReactElement;

import * as React from 'react';
import type { TableLabel } from '../table';
import { Checkbox } from '../checkbox';
import { ListRow, type RowAction } from '../list';
import type { Noun } from './selection-bar';
import type { Column, DataTableModel } from './use-data-table';
import { SKELETON_ROWS, cellContent } from './data-table-row';

interface CardsProps<Row> {
  label: TableLabel;
  model: DataTableModel<Row>;
  columns: Column<Row>[];
  rowHeader: string;
  noun: Noun;
  scope: string;
  rowHref?: (row: Row) => string;
  rowActions?: (row: Row) => RowAction[];
  swipe: boolean;
  skeleton: boolean;
  busy: boolean;
  locale: string | undefined;
}

/**
 * The narrow layout: ListRow cards (the `card: 'title'` column or the row header as title, the status chip, then up to
 * three `card` fields), with the table header's jobs in a bar above them: select the shown rows, and sort.
 */
export function Cards<Row>(p: CardsProps<Row>) {
  const id = React.useId();
  const { model } = p;
  const sel = model.selection;
  const status = p.columns.find((c) => c.card === 'status');
  const header = p.columns.find((c) => c.id === p.rowHeader)!;
  const lead = p.columns.find((c) => c.card === 'title') ?? header;
  const fields = React.useMemo(
    () =>
      p.columns
        .filter((c): c is Column<Row> & { card: 1 | 2 | 3 } => typeof c.card === 'number' && c.id !== lead.id)
        .sort((a, b) => a.card - b.card)
        .slice(0, 3),
    [p.columns, lead],
  );
  const name =
    'caption' in p.label && p.label.caption != null
      ? { 'aria-labelledby': id }
      : p.label['aria-labelledby'] ? { 'aria-labelledby': p.label['aria-labelledby'] } : { 'aria-label': p.label['aria-label'] };
  const sortable = model.headers.filter((h) => h.sortable);
  const current = model.view.sort[0];
  // Only a sort the select can show; a sort on a non-sortable column reads as "Not sorted".
  const currentValue = current && sortable.some((h) => h.column.id === current.columnId) ? `${current.columnId}:${current.direction}` : '';
  return (
    <div className="ld-dt-cards">
      {'caption' in p.label && p.label.caption != null ? <p id={id} className="ld-table-caption">{p.label.caption}</p> : null}
      {/* Mounted through the skeleton, as the table's header is, so a sort answered with a skeleton keeps its focus. */}
      {sel.enabled || sortable.length > 0 ? (
        <div className="ld-dt-cardbar">
          {sel.enabled ? (
            <label className="ld-dt-cardbar-check">
              <Checkbox
                checked={sel.page === 'all'}
                indeterminate={sel.page === 'some'}
                disabled={model.rows.length === 0 || sel.inert}
                onChange={sel.togglePage}
              />
              <span>{`Select all ${p.noun.other} ${p.scope}`}</span>
            </label>
          ) : null}
          {sortable.length ? (
            <label className="ld-dt-cardbar-sort">
              <span>Sort</span>
              <select
                className="ld-dt-select"
                value={currentValue}
                onChange={(e) => {
                  const v = e.currentTarget.value;
                  const at = v.lastIndexOf(':');
                  if (at > 0) model.sortBy(v.slice(0, at), v.slice(at + 1) as 'ascending' | 'descending');
                }}
              >
                {currentValue ? null : <option value="">Not sorted</option>}
                {sortable.flatMap((h) => [
                  <option key={`${h.column.id}:a`} value={`${h.column.id}:ascending`}>{`${h.column.label}, ascending`}</option>,
                  <option key={`${h.column.id}:d`} value={`${h.column.id}:descending`}>{`${h.column.label}, descending`}</option>,
                ])}
              </select>
            </label>
          ) : null}
        </div>
      ) : null}
      <ul className="ld-list-body" {...name} aria-busy={p.busy || undefined}>
        {p.skeleton
          ? Array.from({ length: SKELETON_ROWS }, (_, i) => (
              <li key={i} className="ld-row-wrap ld-dt-card-skeleton" aria-hidden="true">
                <div className="ld-row"><span className="ld-skel" /><span className="ld-skel ld-skel-short" /></div>
              </li>
            ))
          : model.rows.map((r) => (
              <Card
                key={r.id}
                id={r.id}
                original={r.original}
                lead={lead}
                status={status}
                fields={fields}
                text={model.text}
                selected={sel.enabled ? sel.isSelected(r.id) : undefined}
                inert={sel.inert}
                toggle={sel.toggle}
                href={p.rowHref?.(r.original)}
                rowActions={p.rowActions}
                swipe={p.swipe}
                locale={p.locale}
              />
            ))}
      </ul>
    </div>
  );
}

interface CardProps<Row> {
  id: string;
  original: Row;
  /** The column the card leads with. The checkbox and menu are named by the row header, through `text`. */
  lead: Column<Row>;
  status: Column<Row> | undefined;
  fields: Array<Column<Row>>;
  text: (row: Row, columnId?: string) => string;
  selected: boolean | undefined;
  inert: boolean;
  toggle: (id: string, on: boolean, o?: { range?: boolean }) => void;
  href: string | undefined;
  rowActions: ((row: Row) => RowAction[]) | undefined;
  swipe: boolean;
  locale: string | undefined;
}

/** One card. Memoized like DataRow. Its swipe buttons need the actions up front, so `rowActions` is a memo input. */
const Card = React.memo(function Card<Row>(p: CardProps<Row>) {
  const row = p.original;
  const rowName = p.text(row);
  const actions = p.rowActions?.(row);
  const title = p.lead.cell ? p.lead.cell(row) : p.text(row, p.lead.id);
  // Nothing in the card takes focus: the title is where focus lands on it, as after Load more, as the table's row
  // header is.
  const bare = !p.href && p.selected === undefined && !actions?.length;
  return (
    <ListRow
      rowKey={p.id}
      className={p.selected ? 'ld-dt-card-selected' : undefined}
      title={bare ? <span className="ld-dt-card-title" tabIndex={-1}>{title}</span> : title}
      subtitle={
        p.fields.length ? (
          <>
            {p.fields.map((f, i) => (
              <React.Fragment key={f.id}>
                {i > 0 ? ' ' : null}
                {/* Every field but the last ends with its dot, so a line never starts with one. */}
                <span className="ld-dt-card-field">
                  <span className="ld-sr-only">{`${f.label}: `}</span>
                  {p.text(row, f.id)}
                  {i < p.fields.length - 1 ? (
                    <>
                      <span aria-hidden="true">{'\u00a0·'}</span>
                      <span className="ld-sr-only">, </span>
                    </>
                  ) : null}
                </span>
              </React.Fragment>
            ))}
          </>
        ) : undefined
      }
      value={p.status ? cellContent(p.status, row, p.locale) : undefined}
      href={p.href}
      chevron={false}
      control={
        p.selected !== undefined ? (
          <Checkbox
            aria-label={`Select ${rowName}`}
            checked={p.selected}
            disabled={p.inert}
            onChange={(e) => p.toggle(p.id, e.currentTarget.checked, { range: (e.nativeEvent as MouseEvent).shiftKey })}
          />
        ) : undefined
      }
      actions={actions}
      actionsVisible
      actionsLabel={rowName}
      swipe={p.swipe}
    />
  );
}) as <Row>(p: CardProps<Row>) => React.ReactElement;

import { Button } from '../button';
import type { Noun } from './selection-bar';
import type { Paging } from './use-data-table';

/** Load more, or Previous / Page n of m / Next. */
export function Pager({ paging, noun, busy, locale }: { paging: Paging; noun: Noun; busy: boolean; locale: string | undefined }) {
  if (paging.kind === 'load-more') {
    return paging.hasMore ? (
      <div className="ld-dt-pager">
        <Button variant="tinted" className="ld-dt-btn" aria-disabled={busy || undefined} onClick={() => { if (!busy) paging.onLoadMore(); }}>
          {busy ? 'Loading…' : 'Load more'}
        </Button>
      </div>
    ) : null;
  }
  const { page, pageCount, onPageChange } = paging;
  const go = (to: number) => () => { if (to >= 0 && to < pageCount && to !== page) onPageChange(to); };
  // `aria-disabled` leaves the button focusable, so focus stays on it at the first or last page.
  return (
    <nav className="ld-dt-pager" aria-label={`Pages of ${noun.other}`}>
      <Button variant="gray" className="ld-dt-btn" aria-disabled={page <= 0 || undefined} onClick={go(page - 1)}>Previous</Button>
      <span className="ld-dt-page">{`Page ${(page + 1).toLocaleString(locale)} of ${pageCount.toLocaleString(locale)}`}</span>
      <Button variant="gray" className="ld-dt-btn" aria-disabled={page >= pageCount - 1 || undefined} onClick={go(page + 1)}>Next</Button>
    </nav>
  );
}

import * as React from 'react';
import { createSortedRowModel, rowSortingFeature, tableFeatures, useTable } from '@tanstack/react-table';
import { announce } from '@react-aria/live-announcer';
import type { ColumnWidth, SortDirection } from '../table';
import type { Noun } from './selection-bar';

// ---------------------------------------------------------------------------------------------------------------
// Public types. Lede's own: TanStack types never cross this boundary, so a TanStack major is absorbed in here.
// ---------------------------------------------------------------------------------------------------------------

export type { SortDirection };
export type SortItem = { columnId: string; direction: SortDirection };

/** Everything a saved view stores. Later versions add optional keys; none is ever renamed or removed. */
export type TableView = {
  /** Zero or one item: the table sorts by one column. */
  sort: SortItem[];
  /**
   * What the rows are narrowed to, such as a search term or a status: your own keys and plain JSON values, which the
   * table doesn't interpret and a view can carry into a URL. A new filter, compared by its JSON, clears the selection,
   * so an action never reaches rows that aren't shown. A selection whose content changes in the same render as the
   * filter is kept, so a saved view can be restored. In server mode the filter is part of the view the fetchers are
   * given and of each page's cache key, so put every filter here: one closed over in `fetchRows` starts no new visit
   * and keeps the old filter's cached pages. In client mode it does nothing to the rows: filter `rows` yourself. The
   * same filter written another way (key order, `{}` for none) counts as new and refetches.
   */
  filter?: TableFilter;
};
/** A filter's values: plain JSON, so a view serializes. */
export type FilterValue = string | number | boolean | null | readonly (string | number | boolean | null)[];
export type TableFilter = { readonly [key: string]: FilterValue | undefined };
/** What changed in the view. Later versions add members, so keep a default branch when you switch on `type`. */
export type ViewChange = { type: 'sort'; sort: SortItem[] };

/**
 * Clearing a row's checkbox after "Select all N" adds it to `except`. When rows are deleted on the server, update a
 * controlled selection with `removeFromSelection`: a deleted row leaves `ids` and `except` alike. An uncontrolled
 * selection does this itself: a row that leaves `rows` while the view, the page and `state.rows` stay the same was
 * deleted, and it leaves the selection. A row that leaves with a new page or view stays selected.
 */
export type Selection =
  | { kind: 'ids'; ids: ReadonlySet<string> }
  | { kind: 'all-matching'; except: ReadonlySet<string> };

/**
 * What the table is showing and doing, as independent parts: whose rows, whether more are coming, what failed and
 * when the rows were fetched. Every field is optional: `{}` is a table showing its own, settled rows.
 * - `rows`: whose rows are on screen. `'current'`, the default, are this view's. `'previous'` are the last view's, kept
 *   while this one loads so the layout doesn't jump. `'none'` means nothing is on screen yet: until rows or a failure
 *   arrive, the table shows its loading skeleton, never its empty state.
 * - `fetching`: rows are on the way. With current rows the table shows "Updating…" and stays usable. Otherwise it is
 *   `aria-busy`. useServerRows reports it from the first render, before its first fetch starts.
 * - `since`: when the rows on screen were fetched. Shown when refreshing them failed.
 * - `failure`: the last request failed. `scope` says what failed: `'load'` (this view's or page's rows: an alert, and
 *   previous rows are hidden so they never pass as this view's), `'refresh'` (rows on screen could not be refreshed:
 *   a quiet notice with their age), or `'more'` (the next page: an alert, and Load more retries).
 */
export interface TableState {
  rows?: 'current' | 'previous' | 'none';
  fetching?: boolean;
  since?: Date;
  failure?: { message?: string; retry: () => void; scope: 'load' | 'refresh' | 'more' };
}

/** A count, or a lower bound while the exact figure is computed ("50 of 1,000+"). */
export type Total = number | { atLeast: number };

export function isSelected(selection: Selection, id: string): boolean {
  return selection.kind === 'ids' ? selection.ids.has(id) : !selection.except.has(id);
}

/**
 * The selection after rows were deleted on the server. A deleted row is no longer a member of anything: it leaves
 * an explicit selection, and it leaves an `all-matching` selection's `except` too. Adding it to `except` instead would
 * count it twice once the server's new total arrives (the total already excludes it).
 */
export function removeFromSelection(selection: Selection, deleted: Iterable<string>): Selection {
  const gone = new Set(deleted);
  if (selection.kind === 'ids') {
    if (![...gone].some((id) => selection.ids.has(id))) return selection;
    return { kind: 'ids', ids: new Set([...selection.ids].filter((id) => !gone.has(id))) };
  }
  if (![...gone].some((id) => selection.except.has(id))) return selection;
  return { kind: 'all-matching', except: new Set([...selection.except].filter((id) => !gone.has(id))) };
}

export type Column<Row> = {
  /** Stable: views key on it. */
  id: string;
  /** Plain-text name, used for announcements, card labels and checkbox names. */
  label: string;
  /** Richer header content. Defaults to `label`. */
  header?: React.ReactNode;
  /** Defaults to the formatted `value`. */
  cell?: (row: Row) => React.ReactNode;
  /** One accessor for client sort and card text. */
  value?: (row: Row) => string | number | Date | null;
  /** Client sort override, ascending order. */
  compare?: (a: Row, b: Row) => number;
  /**
   * Offers a sort on this column. In client mode the table sorts by `compare`, else by `value`, so the column needs one
   * of them. In server mode the server sorts: the table reports the new view through `onViewChange` and needs neither.
   */
  sortable?: boolean;
  /** `'end'` also turns on tabular figures. */
  align?: 'start' | 'end' | 'center';
  width?: ColumnWidth;
  /** One line with an ellipsis; the full text on hover and focus. */
  truncate?: boolean;
  /**
   * Card layout slot. Omit to leave the column out of cards. `'title'` leads the card (the row header does when no
   * column takes it) while checkboxes and menus stay named by the row header, so a title that repeats across rows still
   * leaves each row a unique name. When a `'title'` column leads, give the row header a numbered slot, so the card
   * shows the name its checkbox and menu carry. 1, 2 and 3 make the line under the title: each field keeps to one line,
   * and one wider than the card wraps inside itself. `'status'` sits beside the text, where a long status narrows it,
   * or under the text in a card narrower than 440px.
   */
  card?: 'title' | 'status' | 1 | 2 | 3;
};

/**
 * Define columns once, at module scope, or in `useMemo` when they depend on props. Rows are memoized against the
 * array: the same array means a sort or a selection re-renders no row, or only the row that changed.
 */
export function defineColumns<Row>(columns: Column<Row>[]): Column<Row>[] {
  return columns;
}

// Bundlers replace `process.env.NODE_ENV` at build time. It's declared here so apps without Node's types type-check.
declare const process: { env: { NODE_ENV?: string } };

/**
 * Development only: warn once when a memo input of the table gets a new identity on several renders in a row, which
 * silently re-renders every row. The usual cause is an inline array or function in the caller's render.
 */
export function useStableInput(value: unknown, name: string, fix: string) {
  const seen = React.useRef<{ value: unknown; changes: number; warned: boolean }>({ value, changes: 0, warned: false });
  React.useEffect(() => {
    if (process.env.NODE_ENV === 'production') return;
    const s = seen.current;
    if (value === s.value) { s.changes = 0; return; }
    s.value = value;
    s.changes += 1;
    if (s.changes >= 3 && !s.warned) {
      s.warned = true;
      console.warn(`DataTable: \`${name}\` is a new ${typeof value === 'function' ? 'function' : 'array'} on every render, so every row re-renders. ${fix}`);
    }
  });
}

export type Paging =
  | { kind: 'load-more'; hasMore: boolean; onLoadMore: () => void }
  | { kind: 'pages'; page: number; pageCount: number; onPageChange: (page: number) => void };

/** The data props shared by `useDataTable` and `DataTable`. */
export interface DataTableOptions<Row> {
  /**
   * Keep this array stable: `defineColumns` at module scope, or `useMemo`. Rows are memoized against it, so a new array
   * on every render re-renders every row and rebuilds the column model. Development builds warn when it does.
   */
  columns: Column<Row>[];
  rows: readonly Row[];
  getRowId: (row: Row) => string;
  /** The column whose cells are `<th scope="row">`. */
  rowHeader: string;
  noun: Noun;
  /** Controlled view. */
  view?: TableView;
  /** Uncontrolled starting view. */
  defaultView?: TableView;
  onViewChange?: (view: TableView, change: ViewChange) => void;
  /** `'client'` sorts `rows`, and `'server'` shows them as given and reports view changes. Default `'client'`. */
  processing?: 'client' | 'server';
  selectionMode?: 'none' | 'multiple';
  selection?: Selection;
  onSelectionChange?: (selection: Selection) => void;
  total?: Total;
  /**
   * Paging, rendered by DataTable. The hook reads its page, so rows that leave with a page change stay selected: pass it
   * to `useDataTable` too when you render your own pager.
   */
  paging?: Paging;
  /**
   * What the table is showing and doing (see `TableState`). While `rows` is `'previous'`, the rows on screen are the
   * last view's, so selection is inert: checking them, the page or "Select all" does nothing until this view's rows
   * arrive.
   */
  state?: TableState;
  /** A BCP 47 tag, such as `'en-US'`, for formatting and client-mode sorting. Default: the browser's locale. */
  locale?: string;
}

export interface HeaderModel<Row> {
  column: Column<Row>;
  sortable: boolean;
  /** This column's sort, or `null`. */
  sort: SortDirection | null;
  isRowHeader: boolean;
}
export interface RowModel<Row> {
  id: string;
  original: Row;
  /** Position in display order. */
  index: number;
}
export interface SelectionModel {
  enabled: boolean;
  value: Selection;
  /** For SelectionBar. */
  count: Total;
  isSelected: (id: string) => boolean;
  /** `range` (Shift) selects every row between the last toggled row and this one. Stable identity. */
  toggle: (id: string, selected: boolean, options?: { range?: boolean }) => void;
  /** The header checkbox: rows on this page. */
  page: 'none' | 'some' | 'all';
  togglePage: () => void;
  /** Every page row is selected and more rows match: offer "Select all N". */
  canSelectAllMatching: boolean;
  /** The rows on screen are the last view's (`state.rows` is `'previous'`): render the checkboxes disabled. */
  inert: boolean;
  selectAllMatching: () => void;
  clear: () => void;
}
export interface DataTableModel<Row> {
  view: TableView;
  headers: HeaderModel<Row>[];
  /** Visible rows, in display order. */
  rows: RowModel<Row>[];
  rowHeader: Column<Row>;
  /** Sort by a column. Without a direction it toggles (ascending first). Announces the new sort politely. */
  sortBy: (columnId: string, direction?: SortDirection) => void;
  selection: SelectionModel;
  /** A column's value as display text: the row header's names checkboxes and menus. */
  text: (row: Row, columnId?: string) => string;
}

// ---------------------------------------------------------------------------------------------------------------

const features = tableFeatures({ rowSortingFeature, sortedRowModel: createSortedRowModel() });
const EMPTY_VIEW: TableView = { sort: [] };
const NO_IDS: Selection = { kind: 'ids', ids: new Set() };
type LocaleIntl = { collator: Intl.Collator; date: Intl.DateTimeFormat; number: Intl.NumberFormat };
const intlByLocale = new Map<string | undefined, LocaleIntl>();
/** A locale's collator and formatters, built once and shared by every table that uses it. */
function intl(locale: string | undefined): LocaleIntl {
  let f = intlByLocale.get(locale);
  if (!f) {
    f = {
      collator: new Intl.Collator(locale, { numeric: true, sensitivity: 'base' }),
      date: new Intl.DateTimeFormat(locale, { day: 'numeric', month: 'short', year: 'numeric' }),
      number: new Intl.NumberFormat(locale),
    };
    intlByLocale.set(locale, f);
  }
  return f;
}

/** Default display text for a value, in `locale` (default: the browser's). */
export function formatValue(v: string | number | Date | null | undefined, locale?: string): string {
  if (v == null) return '';
  if (v instanceof Date) return intl(locale).date.format(v);
  if (typeof v === 'number') return intl(locale).number.format(v);
  return v;
}
const sortKey = (v: string | number | Date | null | undefined) => (v == null ? undefined : v instanceof Date ? v.getTime() : v);
const lowerBound = (t: Total | undefined) => (t == null ? undefined : typeof t === 'number' ? t : t.atLeast);
const members = (s: Selection) => (s.kind === 'ids' ? s.ids : s.except);
function sameSelection(a: Selection, b: Selection | undefined): boolean {
  if (a === b) return true;
  if (!b || a.kind !== b.kind) return false;
  const x = members(a), y = members(b);
  return x.size === y.size && [...x].every((id) => y.has(id));
}

export function useDataTable<Row>(options: DataTableOptions<Row>): DataTableModel<Row> {
  const { columns, rows, getRowId, rowHeader, processing = 'client', selectionMode = 'none', total, locale } = options;
  useStableInput(columns, 'columns', 'Define them with defineColumns() at module scope, or in useMemo.');

  // View: controlled or not.
  const [innerView, setInnerView] = React.useState<TableView>(options.defaultView ?? EMPTY_VIEW);
  const view = options.view ?? innerView;

  // TanStack column definitions, rebuilt only when the columns, the locale or the processing change. The server sorts
  // in server mode, so a column needs no accessor there to be sortable.
  const { collator } = intl(locale);
  const canSort = React.useCallback(
    (c: Column<Row>) => !!c.sortable && (processing === 'server' || !!(c.value || c.compare)),
    [processing],
  );
  const defs = React.useMemo(
    () =>
      columns.map((c) => ({
        id: c.id,
        accessorFn: (r: Row) => sortKey(c.value?.(r)),
        enableSorting: canSort(c),
        // Missing values sort last, except for compare-only columns: their accessor is always `undefined`, and TanStack
        // would then skip the comparator entirely.
        sortUndefined: c.compare ? (false as const) : ('last' as const),
        sortFn: c.compare
          ? (a: { original: Row }, b: { original: Row }) => c.compare!(a.original, b.original)
          : (a: { getValue: (id: string) => unknown }, b: { getValue: (id: string) => unknown }, id: string) => {
              const x = a.getValue(id) as string | number;
              const y = b.getValue(id) as string | number;
              return typeof x === 'number' && typeof y === 'number' ? x - y : collator.compare(String(x), String(y));
            },
      })),
    [columns, collator, canSort],
  );
  // TanStack sorts again when the sorting state or the rows change, but not the comparator. A new collator gives the
  // sorting state a new identity, so a locale change re-sorts the rows on screen.
  const sorting = React.useMemo(
    () => view.sort.map((s) => ({ id: s.columnId, desc: s.direction === 'descending' })),
    [view.sort, collator],
  );
  const getId = React.useRef(getRowId);
  getId.current = getRowId; // read by TanStack while it builds the row model, during render
  const table = useTable(
    {
      features,
      // The defs are structurally TanStack column defs; the cast keeps the generic Row out of TanStack's inference.
      columns: defs as never,
      // Row is any caller type; TanStack wants an object type. Rows pass through untouched.
      data: rows as unknown as Array<Record<string, unknown>>,
      getRowId: (r: Record<string, unknown>) => getId.current(r as unknown as Row),
      state: { sorting },
      onSortingChange: () => undefined, // sorting is driven by `view`
      manualSorting: processing === 'server',
      enableMultiSort: false,
      enableSortingRemoval: false,
    },
    (s) => s.sorting,
  );
  const tsRows = table.getRowModel().rows;
  const visible = React.useMemo<RowModel<Row>[]>(
    () => tsRows.map((r, index) => ({ id: r.id, original: r.original as unknown as Row, index })),
    [tsRows],
  );

  const byId = React.useMemo(() => new Map(columns.map((c) => [c.id, c])), [columns]);
  const headerColumn = byId.get(rowHeader);
  if (!headerColumn) throw new Error(`useDataTable: rowHeader "${rowHeader}" is not a column id`);
  const text = React.useCallback(
    (row: Row, columnId?: string) => {
      const c = columnId ? byId.get(columnId) : headerColumn;
      const v = c?.value?.(row);
      return v == null && c === headerColumn ? getId.current(row) : formatValue(v, locale);
    },
    [byId, headerColumn, locale],
  );

  // Latest values for event handlers, written after commit (never during render).
  const viewRef = React.useRef(view);
  const onViewChangeRef = React.useRef(options.onViewChange);
  React.useLayoutEffect(() => {
    viewRef.current = view;
    onViewChangeRef.current = options.onViewChange;
  });
  const sortBy = React.useCallback(
    (columnId: string, direction?: SortDirection) => {
      const col = byId.get(columnId);
      if (!col) return;
      const current = viewRef.current.sort.find((s) => s.columnId === columnId)?.direction;
      const next: SortDirection = direction ?? (current === 'ascending' ? 'descending' : 'ascending');
      const sort: SortItem[] = [{ columnId, direction: next }];
      const nextView: TableView = { ...viewRef.current, sort };
      if (!options.view) setInnerView(nextView);
      onViewChangeRef.current?.(nextView, { type: 'sort', sort });
      // VoiceOver on macOS and TalkBack don't announce `aria-sort` changes, and this does. It clears after a second,
      // so the same sort twice is announced twice.
      announce(`Sorted by ${col.label}, ${next}`, 'polite', 1000);
    },
    [byId, options.view],
  );
  const headers = React.useMemo<HeaderModel<Row>[]>(
    () =>
      columns.map((c) => ({
        column: c,
        sortable: canSort(c),
        sort: view.sort.find((s) => s.columnId === c.id)?.direction ?? null,
        isRowHeader: c.id === rowHeader,
      })),
    [columns, view.sort, rowHeader, canSort],
  );

  // Selection: Lede's own model (`ids`, or `all-matching` with `except`). TanStack's `Record<id, true>` can't express
  // "all matching except these", and Shift ranges come from the native checkbox's click.
  const [innerSel, setInnerSel] = React.useState<Selection>(NO_IDS);
  const selection = options.selection ?? innerSel;
  // While the rows on screen are the last view's, checking one would select a row this view may not have: nothing
  // selects.
  const inert = options.state?.rows === 'previous';
  const latest = React.useRef({ selection, visible, controlled: !!options.selection, onChange: options.onSelectionChange, inert });
  React.useLayoutEffect(() => {
    latest.current = { selection, visible, controlled: !!options.selection, onChange: options.onSelectionChange, inert };
  });
  const anchor = React.useRef<string | null>(null);
  const commit = React.useCallback((next: Selection) => {
    if (!latest.current.controlled) setInnerSel(next);
    latest.current.onChange?.(next);
  }, []);
  // A selection belongs to the filter it was made under: its count is figured against the total in view, and an action
  // goes to its rows. So a new filter clears it, checked rows included, and no action reaches rows that aren't shown.
  // A selection that changed in the same render as the filter came with it (a saved view being restored), so it stays.
  // Changed by content: an app that builds its selection during render passes a new object every time.
  const filterKey = JSON.stringify(view.filter ?? null);
  const lastFilter = React.useRef(filterKey);
  const lastSelectionProp = React.useRef(options.selection);
  React.useLayoutEffect(() => {
    const setWithIt = options.selection !== undefined && !sameSelection(options.selection, lastSelectionProp.current);
    lastSelectionProp.current = options.selection;
    if (lastFilter.current === filterKey) return;
    lastFilter.current = filterKey;
    anchor.current = null;
    if (setWithIt) return;
    const sel = latest.current.selection;
    if (sel.kind === 'ids' && sel.ids.size === 0) return;
    commit(NO_IDS);
  });
  // A row that leaves `rows` while the view, the page and `state.rows` stay the same was deleted: it leaves an
  // uncontrolled selection, so the bar's count and the next action skip it. A row that leaves with a new page or view
  // is elsewhere and stays selected, as do rows that change while the last view's are on screen. A controlled
  // selection is the caller's: `removeFromSelection` does the same there.
  const shows = options.state?.rows ?? 'current';
  const place = JSON.stringify([view.sort, view.filter ?? null, options.paging?.kind === 'pages' ? options.paging.page : null]);
  const lastRows = React.useRef<{ ids: ReadonlySet<string>; place: string; current: boolean } | null>(null);
  React.useLayoutEffect(() => {
    const ids = new Set(visible.map((r) => r.id));
    const was = lastRows.current;
    lastRows.current = { ids, place, current: shows === 'current' };
    if (!was || !was.current || shows !== 'current' || was.place !== place || latest.current.controlled) return;
    const gone = [...was.ids].filter((id) => !ids.has(id));
    if (gone.length === 0) return;
    const next = removeFromSelection(latest.current.selection, gone);
    if (next !== latest.current.selection) commit(next);
  }, [visible, place, shows, commit]);
  const setMany = React.useCallback(
    (ids: readonly string[], on: boolean) => {
      if (latest.current.inert) return;
      const sel = latest.current.selection;
      if (sel.kind === 'ids') {
        const next = new Set(sel.ids);
        for (const id of ids) if (on) next.add(id); else next.delete(id);
        commit({ kind: 'ids', ids: next });
      } else {
        const next = new Set(sel.except);
        for (const id of ids) if (on) next.delete(id); else next.add(id);
        commit({ kind: 'all-matching', except: next });
      }
    },
    [commit],
  );
  const toggle = React.useCallback(
    (id: string, on: boolean, opts?: { range?: boolean }) => {
      if (latest.current.inert) return; // before the anchor: an ignored toggle mustn't move a later Shift range's start
      const order = latest.current.visible;
      const from = opts?.range && anchor.current != null ? order.findIndex((r) => r.id === anchor.current) : -1;
      const to = from >= 0 ? order.findIndex((r) => r.id === id) : -1;
      anchor.current = id;
      if (from >= 0 && to >= 0) {
        const [a, b] = from < to ? [from, to] : [to, from];
        setMany(order.slice(a, b + 1).map((r) => r.id), on);
      } else setMany([id], on);
    },
    [setMany],
  );
  const isRowSelected = React.useCallback((id: string) => isSelected(selection, id), [selection]);
  let onPage = 0;
  for (const r of visible) if (isRowSelected(r.id)) onPage++;
  const page = onPage === 0 ? 'none' : onPage === visible.length ? 'all' : 'some';
  const bound = lowerBound(total);
  const count: Total =
    selection.kind === 'ids'
      ? selection.ids.size
      : total == null
        ? Math.max(0, visible.length - selection.except.size)
        : typeof total === 'number'
          ? Math.max(0, total - selection.except.size)
          : { atLeast: Math.max(0, total.atLeast - selection.except.size) };

  const selectionModel: SelectionModel = {
    enabled: selectionMode === 'multiple',
    value: selection,
    count,
    isSelected: isRowSelected,
    toggle,
    page,
    togglePage: () => setMany(visible.map((r) => r.id), page !== 'all'),
    canSelectAllMatching: !inert && selection.kind === 'ids' && page === 'all' && bound != null && bound > visible.length,
    selectAllMatching: () => { if (!latest.current.inert) commit({ kind: 'all-matching', except: new Set() }); },
    inert,
    clear: () => { anchor.current = null; commit({ kind: 'ids', ids: new Set() }); },
  };

  return { view, headers, rows: visible, rowHeader: headerColumn, sortBy, selection: selectionModel, text };
}

